<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/dashboard_layout.php';
$user = require_role('customer');
$statement = db()->prepare('SELECT o.*,u.full_name agent_name FROM orders o LEFT JOIN users u ON u.id=o.delivery_agent_id WHERE o.customer_id=? ORDER BY o.created_at DESC');
$statement->execute([$user['id']]);
$orders = $statement->fetchAll();
dashboard_start('Order History', 'history', $user);
?>
<section class="welcome-panel"><div><span class="eyebrow">Order archive</span><h2>Every delivery, organized.</h2><p>Search orders, inspect payment status and open complete invoice details.</p></div><a class="btn" href="<?= url('customer/place_order.php') ?>"><i class="fa-solid fa-plus"></i> New Order</a></section>
<section class="panel"><div class="toolbar"><input data-table-filter="#history-table" placeholder="Search tracking, fuel, agent or status..."></div><div class="table-wrap"><table id="history-table"><thead><tr><th>Tracking Code</th><th>Fuel Details</th><th>Order Total</th><th>Assigned Agent</th><th>Live Status</th><th>Invoice</th></tr></thead><tbody><?php foreach($orders as $order): ?><tr><td><a href="<?= url('customer/track_order.php?code='.urlencode($order['tracking_code'])) ?>"><strong><?= e($order['tracking_code']) ?></strong></a><br><small><?= e(date('d M Y, h:i A',strtotime($order['created_at']))) ?></small></td><td><?= e($order['fuel_type']) ?><br><small><?= e($order['quantity_liters']) ?> litres @ <?= money($order['price_per_liter']) ?></small></td><td><span class="money-tag"><?= money($order['total_amount']) ?></span><br><span class="badge <?= status_class($order['payment_status']) ?>"><?= e($order['payment_status']) ?></span></td><td><?= e($order['agent_name'] ?: 'Not assigned') ?></td><td><span class="badge <?= status_class($order['order_status']) ?>"><?= e($order['order_status']) ?></span></td><td><button class="btn btn-secondary btn-small" type="button" data-invoice-open="invoice-<?= (int)$order['id'] ?>"><i class="fa-solid fa-file-invoice"></i> View</button></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php foreach($orders as $order): ?><div class="invoice-modal" id="invoice-<?= (int)$order['id'] ?>"><div class="modal-card"><button class="modal-close" data-modal-close><i class="fa-solid fa-xmark"></i></button><span class="eyebrow">SmartFuel invoice</span><h2 style="color:var(--text);margin-bottom:20px"><?= e($order['tracking_code']) ?></h2><div class="price-row"><span>Fuel</span><strong><?= e($order['fuel_type']) ?></strong></div><div class="price-row"><span>Quantity</span><strong><?= e($order['quantity_liters']) ?> L × <?= money($order['price_per_liter']) ?></strong></div><div class="price-row"><span>Delivery fee</span><strong><?= money($order['delivery_fee']) ?></strong></div><div class="price-row"><span>Tax</span><strong><?= money($order['tax_amount']) ?></strong></div><div class="price-row total"><span>Invoice total</span><strong><?= money($order['total_amount']) ?></strong></div><p style="margin-top:18px;font-size:.72rem"><?= e($order['delivery_address']) ?> · <?= e($order['delivery_pincode']) ?></p></div></div><?php endforeach; ?>
<?php dashboard_end(); ?>
